// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // Precondition: the caller is the current owner; we set owner to be this contract
        // so that onlyOwner passes. We also need to avoid the zero address case for newOwner.
        vm.assume(newOwner != address(0));
        vm.prank(c.owner());
        c.transferOwnership(newOwner);
        assertTrue(c.owner() == newOwner);
    }
}

